const user = {
  name: _faker.faker.person.fullName(),
  email: _faker.faker.internet.email(),
  password: _faker.faker.internet.password(),
  title: 'Mr',
  birth_date: '10',
  birth_month: '5',
  birth_year: '1998',
  firstname: _faker.faker.person.firstName(),
  lastname: _faker.faker.person.lastName(),
  company: _faker.faker.company.name(),
  address1: _faker.faker.location.streetAddress(),
  address2: _faker.faker.location.secondaryAddress(),
  country: 'Canada',
  zipcode: _faker.faker.location.zipCode(),
  state: _faker.faker.location.state(),
  city: _faker.faker.location.city(),
  mobile_number: _faker.faker.phone.number()
};
cy.request({
  method: 'POST',
  url: 'https://automationexercise.com/api/createAccount',
  form: true,
  body: user
}).then(response => {
  expect(response.status).to.eq(200);
  const body = JSON.parse(response.body);
  expect(body.responseCode).to.eq(201);
  expect(body.message).to.eq('User created!');
  cy.wait(3000);
});

const duplicatedUser = {
  name: 'Gabriel',
  email: 'teste@email.com',
  password: '123456',
  title: 'Mr',
  birth_date: '10',
  birth_month: '5',
  birth_year: '1998',
  firstname: 'Gabriel',
  lastname: 'Alexandria',
  company: 'QA',
  address1: 'Street 1',
  address2: 'Street 2',
  country: 'Canada',
  zipcode: '12345',
  state: 'Bahia',
  city: 'Salvador',
  mobile_number: '71999999999'
};
cy.request({
  method: 'POST',
  url: 'https://automationexercise.com/api/createAccount',
  failOnStatusCode: false,
  form: true,
  body: duplicatedUser
}).then(response => {
  expect(response.status).to.eq(200);
  const body = JSON.parse(response.body);
  expect(body.responseCode).to.eq(400);
  expect(body.message).to.include('Email already exists');
  cy.wait(3000);
});
